-- ---------------------------------------------------------------------
-- GUARD: staging harus persis 826 baris / Rp 507.736.562
-- Kalau tidak, script ini BATAL dan tidak ada data yang masuk.
-- ---------------------------------------------------------------------
DO $guard$
DECLARE n int; v numeric;
BEGIN
  SELECT count(*), COALESCE(sum(nominal),0) INTO n, v FROM payment_import_staging;
  IF n <> 826 THEN
    RAISE EXCEPTION 'GAGAL: staging berisi % baris, harusnya 826', n;
  END IF;
  IF v <> 507736562 THEN
    RAISE EXCEPTION 'GAGAL: total nominal staging % , harusnya 507736562', v;
  END IF;
END $guard$;

-- GUARD 2: tidak boleh ada dua baris dengan kunci yang sama persis.
-- Kunci = username + campaign + status + nominal + tanggal.
--nol Duplikat SEBENARNYA adalah 0, jadi ini harus lolos tanpa perubahan.
-- Kalau gagal, berarti parse menghasilkan baris kembar -> perbaiki parser,
-- JANGAN dihapus diam-diam dari staging.
DO $guard2$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (
    SELECT 1 FROM payment_import_staging
    GROUP BY username, campaign_sheet, status_klaim, nominal, tanggal
    HAVING count(*) > 1
  ) d;
  IF n > 0 THEN
    RAISE EXCEPTION 'GAGAL: % grup baris kembar di staging', n;
  END IF;
END $guard2$;

COMMIT;

